func Pool(input []int) []int {
    jobs := make(chan int, len(input))
    results := make(chan int, len(input))
    for worker := 0; worker < 2; worker++ {
        go func() { for job := range jobs { results <- job * job } }()
    }
    for _, job := range input { jobs <- job }; close(jobs)
    out := make([]int, 0, len(input))
    for range input { out = append(out, <-results) }
    return out
}

func ProducerConsumer() int {
    items := make(chan int, 2)
    go func() { for _, v := range []int{1, 2, 3} { items <- v }; close(items) }()
    total := 0
    for v := range items { total += v }
    return total
}

type Command struct { delta int; read bool; reply chan int }
func Counter(in <-chan Command) {
    total := 0
    for c := range in {
        if !c.read { total += c.delta }
        c.reply <- total
    }
}

type Request struct { value int; reply chan int }
type Active chan Request
func NewActive() Active {
    a := make(Active)
    go func() { for r := range a { r.reply <- r.value * 2 } }()
    return a
}
func (a Active) Submit(value int) <-chan int {
    reply := make(chan int, 1)
    a <- Request{value, reply}; return reply
}

func Reactor(ready <-chan int, readReady func(int) int,
             unregister func(int), write func(int)) {
    for fd := range ready {
        n := readReady(fd)
        if n > 0 { write(n) }
        if n < 0 { unregister(fd) }
    }
}

type Completion struct { token, bytes int }
func Proactor(submit func(int, int, chan<- Completion), write func(int)) {
    completed := make(chan Completion, 1)
    submit(3, 7, completed)
    for c := range completed {
        if c.token == 7 { write(c.bytes); return }
    }
}

import "sync"
type Future struct { once sync.Once; done chan struct{}; value int }
func NewFuture() *Future { return &Future{done: make(chan struct{})} }
func (f *Future) Resolve(value int) {
    f.once.Do(func() { f.value = value; close(f.done) })
}
func (f *Future) Get() int { <-f.done; return f.value }

func HalfSync(frames <-chan int, write func(int)) {
    jobs := make(chan int, 2)
    done := make(chan struct{})
    go func() {
        for frame := range jobs { write(frame * frame) }
        close(done)
    }()
    for frame := range frames { jobs <- frame }
    close(jobs); <-done
}

import ("context"; "sync")
type Outcome struct { value int; err error }
func Scope(a, b func(context.Context) (int, error)) (int, error) {
    ctx, cancel := context.WithCancel(context.Background()); defer cancel()
    out := make(chan Outcome, 2)
    var wg sync.WaitGroup
    for _, fn := range []func(context.Context)(int,error){a,b} {
        wg.Add(1)
        go func(f func(context.Context)(int,error)) {
            defer wg.Done(); v,e := f(ctx); out <- Outcome{v,e}
        }(fn)
    }
    total := 0; var first error
    for i:=0; i<2; i++ {
        r := <-out
        if r.err != nil && first == nil { first = r.err; cancel() }
        total += r.value
    }
    wg.Wait(); return total, first
}

func Supervise(run func() error) error {
    for attempt:=0; attempt<2; attempt++ {
        done := make(chan error, 1)
        go func() { done <- run() }()
        err := <-done
        if err == nil { return nil }
        if attempt == 1 { return err }
    }
    return nil
}

import "sync"
func MapReduce(parts [][]int) map[int]int {
    keys := make(chan int)
    var wg sync.WaitGroup
    for _, part := range parts {
        wg.Add(1)
        go func(xs []int) {
            defer wg.Done()
            for _, x := range xs { keys <- x % 2 }
        }(part)
    }
    go func(){ wg.Wait(); close(keys) }()
    totals := map[int]int{0:0,1:0}
    for key := range keys { totals[key]++ }
    return totals
}
